/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 python - <<'PY'
from service import offset

for page in (1, 2, 4, 100, 10**20):
    for size in range(1, 101):
        assert offset(page, size) == (page - 1) * size
for value in (-100, -1, 0, 1.0, 1.5, '1', None, True, False, [], {}):
    try:
        offset(value, 10)
    except ValueError:
        pass
    else:
        raise AssertionError(('page', value))
for value in (-100, -1, 0, 101, 1000, 1.0, 1.5, '1', None, True, False, [], {}):
    try:
        offset(1, value)
    except ValueError:
        pass
    else:
        raise AssertionError(('size', value))
print('Pagination boundary and validation checks passed')
PY
